def balanced(s: str) -> bool:
    """Return whether brackets in *s* are balanced and correctly nested.

    Brackets inside double-quoted strings are ignored. A backslash inside a
    double-quoted string escapes the following character. An unterminated
    string is considered unbalanced.
    """
    opening = "([{"
    closing = {')': '(', ']': '[', '}': '{'}
    stack: list[str] = []
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            in_string = True
        elif char in opening:
            stack.append(char)
        elif char in closing:
            if not stack or stack.pop() != closing[char]:
                return False

    return not in_string and not stack
